compile.workshop:
variables {
    global:
        0: g
    player:
        0: P
}

rule ("chase keyword forms") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Chase Global Variable At Rate(g, 10, 2, None);
        Chase Global Variable Over Time(g, 10, 3, None);
        Chase Player Variable At Rate(Event Player, P, 0, 1, None);
        Chase Global Variable Over Time(g, 10, 3, Destination and Duration);
        Chase Global Variable Over Time(g, 10, 3, None);
        Wait(1, Ignore Condition);
        Set Global Variable(g, Vector(1, 2, 3));
        Set Global Variable(g, 2);
        Create HUD Text(All Players(All Teams), Custom String("x"), Custom String("                                                                                                                             {0}", Custom String("                                             ")), Null, Left, -9999, Color(Orange), Null, Null, Visible To and String, Default Visibility);
        Set Global Variable(g, Players Within Radius(Vector(0, 0, 0), 10, All Teams, Off));
        Set Status(Event Player, Event Player, Rooted, 2);
    }
}

